package com.fluxisai.subscription;
import static org.junit.jupiter.api.Assertions.assertEquals; import java.math.*; import java.time.*; import java.util.UUID; import org.junit.jupiter.api.Test;
class SubscriptionServiceTest { @Test void monthlyAndAnnualKeepCurrencyAmountsSeparate(){var user=UUID.randomUUID();var monthly=new Subscription(user,"Hosting","Cloud",new BigDecimal("9.22"),"EUR",SubscriptionPeriodicity.MONTHLY,null,null,SubscriptionStatus.ACTIVE,null,null,null);var yearly=new Subscription(user,"Tool","Vendor",new BigDecimal("120.00"),"USD",SubscriptionPeriodicity.YEARLY,null,null,SubscriptionStatus.ACTIVE,null,null,null);assertEquals(0,new BigDecimal("9.22").compareTo(SubscriptionService.monthly(monthly)));assertEquals(0,new BigDecimal("110.64").compareTo(SubscriptionService.annual(monthly)));assertEquals(0,new BigDecimal("10.00").compareTo(SubscriptionService.monthly(yearly)));assertEquals(0,new BigDecimal("120.00").compareTo(SubscriptionService.annual(yearly)));} }
